Here is the extended C# code that maintains the existing functionality while adding the option to export the report in CSV format:

```csharp
using System;
using System.IO;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(csvFilePath))
                {
                    // Write header
                    writer.WriteLine("Field,Value");

                    // Write report data (assuming report has a method or properties to expose data)
                    // This is a generic implementation; adjust based on actual SummaryReport structure
                    writer.WriteLine($"Date,{DateTime.Now:yyyy-MM-dd}");
                    writer.WriteLine($"Status,{report.Status}");
                    writer.WriteLine($"Details,{report.ToString().Replace(",", ";")}"); // Escape commas for CSV
                }

                Console.WriteLine($"Report exported to CSV: {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

// Placeholder for SummaryReport class to make the code compile
public class SummaryReport
{
    public string Status { get; set; } = "Completed";

    public override string ToString()
    {
        return $"Status: {Status}";
    }
}
